def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    doc = None
    try:
        doc = etree.fromstring(encode_if_text(decode_if_bytes(request.body)))
    except Exception:
        pass
    if doc is not None:
        # Check for magic envelope (public message)
        if doc.tag == MAGIC_ENV_TAG:
            return True
        # Check for encrypted (private) message
        if doc.tag == "{%s}header" % PROTOCOL_NS or doc.find(".//{%s}header" % PROTOCOL_NS) is not None:
            return True
        # Check for legacy payload
        if doc.find(".//{}encrypted_header") is not None or doc.tag in ("XML", "post"):
            return True
    # Try JSON-based encrypted payload
    try:
        body = decode_if_bytes(request.body)
        data = json.loads(body)
        if "aes_key" in data and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    return False

