def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Get the set of digests in the manifest (normalized)
    manifest_digests = set(manifest_files.values())
    # Check that every digest used in state blocks is present in the manifest
    for digest in digests_used:
        if digest not in manifest_digests:
            self.error('E050g', digest=digest)
    # Check that every digest in the manifest is used in at least one state block
    digests_used_set = set(digests_used)
    for digest in manifest_digests:
        if digest not in digests_used_set:
            self.warning('W003', digest=digest)

