def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    for parser_name, parser_dict in args.items():
        for spec_option in \
                self.spec_helper.get_parser_option_specs(parser_name):
            option_name = spec_option['name']
            if 'silent' in spec_option:
                silent_list = spec_option['silent']
                if not isinstance(silent_list, list):
                    silent_list = [silent_list]
                if option_name in parser_dict:
                    option_value = parser_dict[option_name]
                    for silent_entry in silent_list:
                        parts = silent_entry.split(':')
                        if len(parts) == 2:
                            silenced_value, silenced_arg = parts
                            if str(option_value) == str(silenced_value):
                                silent_args.append(silenced_arg)
    return silent_args

