    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    # Identifying fields at the first level of a Kubernetes resource
    identifying_fields = {"apiVersion", "kind"}

    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            if first_level and key == "metadata":
                # For the metadata field at first level, copy identifying sub-fields
                # (name and namespace) and set everything else to None recursively
                metadata_result = {}
                for meta_key, meta_value in value.items():
                    if meta_key in ("name", "namespace"):
                        metadata_result[meta_key] = meta_value
                    elif isinstance(meta_value, dict):
                        metadata_result[meta_key] = generate_default_observer_schema_dict(meta_value)
                    elif isinstance(meta_value, list):
                        metadata_result[meta_key] = generate_default_observer_schema_list(meta_value)
                    else:
