def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self.dim == 1:
        edges = self.edges
        # Check if coord is within range
        if coord < edges[0] or coord >= edges[-1]:
            return
        # Binary search for the bin index
        index = hf.get_bin_on_axis(coord, edges)
        if index is None:
            return
        self.bins[index] += weight
    else:
        indices = []
        for i, axis_edges in enumerate(self.edges):
            c = coord[i]
            if c < axis_edges[0] or c >= axis_edges[-1]:
                return
            index = hf.get_bin_on_axis(c, axis_edges)
            if index is None:
                return
            indices.append(index)
        # Navigate to the correct bin
        bins = self.bins
        for idx in indices[:-1]:
            bins = bins[idx]
        bins[indices[-1]] += weight

