def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check id matches
    if self.id is not None and prior.id is not None:
        if self.id != prior.id:
            self.error('E037b', prior_id=prior.id, id=self.id)
    # Check digestAlgorithm matches
    if self.digest_algorithm != prior.digest_algorithm:
        self.error('E066', algorithm=self.digest_algorithm, prior_algorithm=prior.digest_algorithm)
    # Check contentDirectory matches
    if self.content_directory != prior.content_directory:
        self.error('E067', content_directory=self.content_directory, prior_content_directory=prior.content_directory)
    # Check that prior versions are a valid prefix of the current versions
    prior_num_versions = len(prior.all_versions)
    current_num_versions = len(self.all_versions)
    if prior_num_versions > current_num_versions:
        self.error('E046a', prior_head=prior.head, head=self.head)
        return
    # Check that version sequence matches for versions in prior
    for i, v in enumerate(prior.all_versions):
        if i >= len(self.all_versions) or v != self.all_versions[i]:
            self.error('E046b', version=v)
            return
    # Check that version metadata and state blocks match for shared versions
    if self.inventory is not None and prior.inventory is not None:
        current_versions = self.inventory.get('versions', {})
        prior_versions = prior.inventory.get('versions', {})
        for v in prior.all_versions:
            if v not in current_versions or v not in prior_versions:
                continue
            current_version = current_versions[v]
            prior_version = prior_versions[v]
            # Check created matches
            if current_version.get('created') != prior_version.get('created'):
                self.error('E066b', version=v)
            # Check message matches
            if current_version.get('message') != prior_version.get('message'):
                self.error('E066c', version=v)
            # Check user matches
            if current_version.get('user') != prior_version.get('user'):
                self.error('E066d', version=v)
            # Check state matches
            if current_version.get('state') != prior_version.get('state'):
                self.error('E066e', version=v)
        # Check manifest entries for prior versions are consistent
        current_manifest = self.inventory.get('manifest', {})
        prior_manifest = prior.inventory.get('manifest', {})
        # Build reverse maps: file -> digest
        current_file_to_digest = {}
        for digest, files in current_manifest.items():
            norm = normalized_digest(digest, self.digest_algorithm)
            for f in files:
                current_file_to_digest[f] = norm
        prior_file_to_digest = {}
        for digest, files in prior_manifest.items():
            norm = normalized_digest(digest, prior.digest_algorithm)
            for f in files:
                prior_file_to_digest[f] = norm
        # Check that all files in prior manifest that belong to prior versions
        # have consistent digests in the current manifest
        prior_version_set = set(prior.all_versions)
        for f, prior_digest in prior_file_to_digest.items():
            # Check if file belongs to a prior version
            parts = f.split('/', 1)
            if len(parts) >= 1 and parts[0] in prior_version_set:
                if f in current_file_to_digest:
                    if current_file_to_digest[f] != prior_digest:
                        self.error('E066f', path=f)
                else:
                    self.error('E066g', path=f)

