def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    nanoseconds = (value.hour * 3600 + value.minute * 60 + value.second) * 1000000000 + value.nanosecond
    if value.tzinfo is None:
        return Structure(b"t", nanoseconds)
    else:
        offset = value.utcoffset()
        tz_offset_seconds = int(offset.total_seconds())
        return Structure(b"T", nanoseconds, tz_offset_seconds)

