def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        the_fs = open_fs(path)
    except Exception:
        # Not a directory, might be a file
        if fs.path.isfile(path) or '.' in fs.path.basename(path):
            return 'file'
        return 'Not a directory or file: %s' % path
    try:
        namastes = find_namastes(0, the_fs)
    except Exception as e:
        return 'Error reading namastes: %s' % str(e)
    for namaste in namastes:
        if namaste.tvalue.startswith('ocfl_'):
            if 'object' in namaste.tvalue:
                return 'object'
            else:
                return 'root'
    return 'Not an OCFL directory (no 0=ocfl* namaste file found): %s' % path

