def initialize(self):
    """Create and initialize a new OCFL storage root."""
    self.open_root_fs(create=True)
    # Check that the root is empty
    root_entries = list(self.root_fs.listdir('/'))
    if root_entries:
        raise StoreException("OCFL storage root '%s' is not empty, cannot initialize" % self.root)
    # Write the OCFL namaste declaration file
    namaste = Namaste(0, self.declaration_tvalue)
    namaste.write(self.root_fs)
    # Write the spec file if available
    try:
        spec_src_fs = open_fs(fs.path.join(fs.path.dirname(__file__), 'data'))
        if spec_src_fs.isfile(self.spec_file):
            fs.copy.copy_file(spec_src_fs, self.spec_file, self.root_fs, self.spec_file)
    except Exception:
        pass
    # Write the layout file
    layout = {}
    if self.disposition:
        layout['extension'] = self.disposition
    if self.description:
        layout['description'] = self.description
    self.root_fs.writetext(self.layout_file, json.dumps(layout, indent=2))
    logging.info("Initialized OCFL storage root at '%s'", self.root)

