def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    prior_manifest_digests = {}  # index by digest of content path
    prior_fixity_digests = {}  # index by algorithm, then digest of content path
    for version_dir in version_dirs:
        inv_file = fs.path.join(version_dir, 'inventory.json')
        if not self.obj_fs.exists(inv_file):
            self.log.warning('W010', where=version_dir)
        else:
            inventory, inv_validator = self.validate_inventory(
                inv_file, where=version_dir)
            # Determine digest algorithm for this version inventory
            digest_algorithm = inv_validator.digest_algorithm if inv_validator.digest_algorithm else self.digest_algorithm
            self.validate_inventory_digest(inv_file, digest_algorithm, where=version_dir)
            # Check for any content digests that differ from the root inventory
            if inv_validator.manifest is not None:
                for digest, paths in inv_validator.manifest.items():
                    for path in paths:
                        norm_digest = normalized_digest(digest, digest_algorithm)
                        root_digest = self.root_inv_validator.content_path_to_digest.get(path) if self.root_inv_validator and hasattr(self.root_inv_validator, 'content_path_to_digest') else None
                        if root_digest is not None and norm_digest != root_digest:
                            if path not in prior_manifest_digests:
                                prior_manifest_digests[path] = {}
                            prior_manifest_digests[path][digest_algorithm] = digest
            if inv_validator.fixity is not None:
                for algorithm, digest_map in inv_validator.fixity.items():
                    if algorithm not in prior_fixity_digests:
                        prior_fixity_digests[algorithm] = {}
                    for digest, paths in digest_map.items():
                        for path in paths:
                            prior_fixity_digests[algorithm][path] = digest
    return prior_manifest_digests, prior_fixity_digests

