def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    mangled_observer_schema = []

    for resource in app.spec.manifest:
        # Check if a custom observer schema has been specified for this resource
        try:
            idx = get_kubernetes_resource_idx(app.spec.observer_schema, resource)
            # A custom observer schema exists, use it
            mangled_observer_schema.append(deepcopy(app.spec.observer_schema[idx]))
        except IndexError:
            # No custom observer schema, generate a default one with only
            # identifying fields (apiVersion, kind, metadata.name/namespace)
            default_schema = {
                "apiVersion": resource.get("apiVersion", ""),
                "kind": resource["kind"],
                "metadata": {
                    "name": resource["metadata"]["name"],
                },
            }
            if "namespace" in resource.get("metadata", {}):
                default_schema["metadata"]["namespace"] = resource["metadata"]["namespace"]
            mangled_observer_schema.append(default_schema)

    app.status.mangled_observer_schema = mangled_observer_schema

