def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    self.inventory = inventory
    # Check id
    if 'id' not in inventory:
        self.error('E036a')
    else:
        iid = inventory['id']
        if not isinstance(iid, str) or iid == '':
            self.error('E036b')
        else:
            self.id = iid
    # Check type and spec version
    if 'type' not in inventory:
        self.error('E036c')
    else:
        itype = inventory['type']
        if extract_spec_version:
            matched = False
            for spec_version in self.spec_versions_supported:
                if itype == 'https://ocfl.io/' + spec_version + '/spec/#inventory':
                    self.spec_version = spec_version
                    matched = True
                    break
            if not matched:
                self.error('E038a', type=itype)
        else:
            expected_type = 'https://ocfl.io/' + self.spec_version + '/spec/#inventory'
            if itype != expected_type:
                self.error('E038b', type=itype)
    # Check digestAlgorithm
    if 'digestAlgorithm' not in inventory:
        self.error('E036d')
    else:
        digest_algorithm = inventory['digestAlgorithm']
        if not isinstance(digest_algorithm, str):
            self.error('E025a')
        elif digest_algorithm in ('sha512', 'sha256'):
            self.digest_algorithm = digest_algorithm
            if digest_algorithm == 'sha256':
                self.warning('W004', digest_algorithm=digest_algorithm)
        elif self.lax_digests and re.match(r'''[a-z0-9]+''', digest_algorithm):
            self.digest_algorithm = digest_algorithm
            self.warning('W004', digest_algorithm=digest_algorithm)
        else:
            self.error('E025b', digest_algorithm=digest_algorithm)
    # Check head
    if 'head' not in inventory:
        self.error('E036e')
    else:
        head = inventory['head']
        if not isinstance(head, str) or not re.match(r'''v\d+$''', head):
            self.error('E040', head=head)
        else:
            self.head = head
    # Check contentDirectory
    if 'contentDirectory' in inventory:
        content_directory = inventory['contentDirectory']
        if not isinstance(content_directory, str) or content_directory == '' or '/' in content_directory or content_directory in ('.', '..'):
            self.error('E017', content_directory=content_directory)
        else:
            self.content_directory = content_directory
    # Check manifest
    if 'manifest' not in inventory:
        self.error('E041a')
        self.manifest_files = {}
    else:
        manifest = inventory['manifest']
        if not isinstance(manifest, dict):
            self.error('E041b')
            self.manifest_files = {}
        else:
            self.manifest_files = {}
            self.unnormalized_digests = {}
            digest_re = digest_regex(self.digest_algorithm)
            for digest, files in manifest.items():
                if not isinstance(digest, str):
                    self.error('E096', digest=digest)
                    continue
                norm = normalized_digest(digest, self.digest_algorithm)
                if not re.fullmatch(digest_re, digest, re.IGNORECASE):
                    self.error('E096', digest=digest)
                    continue
                if norm != digest:
                    if norm in self.unnormalized_digests:
                        self.error('E097', digest=digest)
                        continue
                    self.unnormalized_digests[norm] = digest
                if not isinstance(files, list):
                    self.error('E092', digest=digest)
                    continue
                for filepath in files:
                    if not isinstance(filepath, str) or filepath == '':
                        self.error('E092', digest=digest)
                    elif filepath in self.manifest_files:
                        self.error('E101', filepath=filepath)
                    else:
                        self.manifest_files[filepath] = norm
    # Check versions
    if 'versions' not in inventory:
        self.error('E041c')
    else:
        versions = inventory['versions']
        if not isinstance(versions, dict):
            self.error('E044')
        else:
            # Build sorted list of version names
            version_names = list(versions.keys())
            # Validate version sequence
            num_versions = len(version_names)
            # Determine zero-padding from head
            head = self.head
            if re.match(r'''v0\d+$''', head):
                # zero-padded
                width = len(head) - 1
                expected_versions = ['v' + str(i).zfill(width) for i in range(1, num_versions + 1)]
            else:
                expected_versions = ['v' + str(i) for i in range(1, num_versions + 1)]
            for vn in expected_versions:
                if vn not in versions:
                    self.error('E010', version=vn)
            if self.head not in versions:
                self.error('E040', head=self.head)
            self.all_versions = [v for v in expected_versions if v in versions]
            # Validate each version
            for version in self.all_versions:
                vdata = versions[version]
                if not isinstance(vdata, dict):
                    self.error('E048', version=version)
                    continue
                # created
                if 'created' not in vdata:
                    self.error('E048', version=version)
                else:
                    created = vdata['created']
                    if not isinstance(created, str):
                        self.error('E049a', version=version)
                    else:
                        try:
                            str_to_datetime(created)
                        except Exception:
                            self.error('E049b', version=version, created=created)
                # message - optional
                if 'message' in vdata:
                    message = vdata['message']
                    if not isinstance(message, str):
                        self.error('E094', version=version)
                # user - optional
                if 'user' in vdata:
                    user = vdata['user']
                    if not isinstance(user, dict):
                        self.error('E054a', version=version)
                    else:
                        if 'name' not in user:
                            self.error('E054b', version=version)
                        else:
                            if not isinstance(user['name'], str):
                                self.error('E054c', version=version)
                        if 'address' in user:
                            if not isinstance(user['address'], str):
                                self.error('E054d', version=version)
                # state
                if 'state' not in vdata:
                    self.error('E048', version=version)
                else:
                    state = vdata['state']
                    if not isinstance(state, dict):
                        self.error('E050a', version=version)
                    else:
                        logical_paths = []
                        digest_re = digest_regex(self.digest_algorithm)
                        for digest, lpaths in state.items():
                            if not isinstance(digest, str) or not re.fullmatch(digest_re, digest, re.IGNORECASE):
                                self.error('E050b', version=version, digest=digest)
                                continue
                            norm = normalized_digest(digest, self.digest_algorithm)
                            if norm not in self.manifest_files and norm not in (self.unnormalized_digests or {}):
                                # Check if digest (possibly unnormalized) is in manifest
                                if digest not in self.manifest_files:
                                    self.error('E050c', version=version, digest=digest)
                            if not isinstance(lpaths, list):
                                self.error('E050d', version=version)
                                continue
                            for lpath in lpaths:
                                if not isinstance(lpath, str) or lpath == '':
                                    self.error('E050e', version=version)
                                elif lpath in logical_paths:
                                    self.error('E095a', version=version, logical_path=lpath)
                                else:
                                    logical_paths.append(lpath)
    # Check fixity - optional
    if 'fixity' in inventory:
        fixity = inventory['fixity']
        if not isinstance(fixity, dict):
            self.error('E056a')
        else:
            for falg, fdict in fixity.items():
                if not isinstance(fdict, dict):
                    self.error('E056b', algorithm=falg)
                    continue
                fixity_re = digest_regex(falg)
                fixity_files = []
                for fdigest, ffiles in fdict.items():
                    if not re.fullmatch(fixity_re, fdigest, re.IGNORECASE):
                        self.error('E057', algorithm=falg, digest=fdigest)
                        continue
                    if not isinstance(ffiles, list):
                        self.error('E057', algorithm=falg, digest=fdigest)
                        continue
                    for ffile in ffiles:
                        if not isinstance(ffile, str):
                            self.error('E057', algorithm=falg, digest=fdigest)
                        elif ffile in fixity_files:
                            self.error('E101', filepath=ffile)
                        else:
                            fixity_files.append(ffile)

