                                self.error('E050b', version=version, digest=digest)
                                continue
                            norm = normalized_digest(digest, self.digest_algorithm)
                            if norm not in self.manifest_files and norm not in (self.unnormalized_digests or {}):
                                # Check if digest (possibly unnormalized) is in manifest
                                if digest not in self.manifest_files:
                                    self.error('E050c', version=version, digest=digest)
                            if not isinstance(lpaths, list):
                                self.error('E050d', version=version)
                                continue
                            for lpath in lpaths:
                                if not isinstance(lpath, str) or lpath == '':
                                    self.error('E050e', version=version)
                                elif lpath in logical_paths:
                                    self.error('E095a', version=version, logical_path=lpath)
                                else:
                                    logical_paths.append(lpath)
    # Check fixity - optional
    if 'fixity' in inventory:
        fixity = inventory['fixity']
        if not isinstance(fixity, dict):
            self.error('E056a')
        else:
            for falg, fdict in fixity.items():
                if not isinstance(fdict, dict):
                    self.error('E056b', algorithm=falg)
                    continue
                fixity_re = digest_regex(falg)
                fixity_files = []
                for fdigest, ffiles in fdict.items():
                    if not re.fullmatch(fixity_re, fdigest, re.IGNORECASE):
                        self.error('E057', algorithm=falg, digest=fdigest)
                        continue
                    if not isinstance(ffiles, list):
                        self.error('E057', algorithm=falg, digest=fdigest)
                        continue
                    for ffile in ffiles:
                        if not isinstance(ffile, str):
                            self.error('E057', algorithm=falg, digest=fdigest)
                        elif ffile in fixity_files:
                            self.error('E101', filepath=ffile)
                        else:
                            fixity_files.append(ffile)
